{
  "status": "verified",
  "input": "sales.csv",
  "output": "monthly_summary.csv",
  "rowCount": 4,
  "columns": [
    "date",
    "amount"
  ],
  "dateRange": {
    "min": "2026-01-01",
    "max": "2026-02-15"
  }

"summary": [
    {
      "month": "2026-01",
      "total": 150,
      "momChange": null,
      "momPct": null
    },
    {
      "month": "2026-02",
      "total": 210,
      "momChange": 60,
      "momPct": 40
    }
  ]

const { headers, rows, summary, minDate, maxDate } = computeMonthlySummary();
writeSummary(summary);
const verification = verifySummary(summary);
if (!verification.ok) {
  console.error(JSON.stringify(verification, null, 2));
  process.exit(1);
}

